\centering
\includegraphics[width=\linewidth]{figures/layer_sweep.pdf}
\caption{Layer sweep (test questions, instructed condition plus neutral hallucinations). The off-policy probes are near-perfect on their own held-out data at every layer (red), yet lie-vs-hallucination performance (orange) stays well below lie-vs-correct (blue) at all layers. The conclusions do not depend on the choice of layer 16.}
\label{fig:layers}
\end{figure}

